			// Use chk.spec_valid (not raw 4-state compares) so the helper actually fires in the
			// same situations as the real objectives.
			if (check && rvfi_valid[0] && chk.spec_valid && !chk.spec_trap && !chk.mem_fault) begin
				h_add_is_32bit: assert(rvfi_insn[1:0] == 2'b11);
				// RVFI rs* address plumbing comes directly from dbg_rs*val_valid + instruction fields.
				// (See picorv32 RISCV_FORMAL assignments: rvfi_rs*_addr <= dbg_rs*val_valid ? dbg_insn_rs* : 0.)
				h_rvfi_rs1_addr_piped: assert(rvfi_rs1_addr == (last_dbg_rs1val_valid ? rvfi_insn[19:15] : 5'd0));
				h_rvfi_rs2_addr_piped: assert(rvfi_rs2_addr == (last_dbg_rs2val_valid ? rvfi_insn[24:20] : 5'd0));
				// ADD always consumes both source operands; the core must have captured both.
				h_add_rs1_captured: assert(last_dbg_rs1val_valid);
				h_add_rs2_captured: assert(last_dbg_rs2val_valid);
				// x0 destination must observe a zero writeback in RVFI.
				h_add_x0_write_suppressed: assert(rvfi_insn[11:7] == 5'd0 ? (rvfi_rd_wdata == 32'd0) : 1'b1);

				// Avoid spurious failure from X-propagation: the check uses 4-state '==' and
				// any X bit on either side makes the assertion evaluate to X (and fail).
				h_add_rvfi_rd_wdata_known: assert(no_x32(rvfi_rd_wdata));
				h_add_spec_rd_wdata_known: assert(no_x32(chk.spec_rd_wdata));

				// Make the spec model's register addressing explicit and 2-state.
				// If these are left X, the model can produce X outputs even with known operands.
				h_add_spec_rs1_addr_known: assert(no_x5(chk.spec_rs1_addr));
				h_add_spec_rs2_addr_known: assert(no_x5(chk.spec_rs2_addr));
				h_add_spec_rd_addr_known: assert(no_x5(chk.spec_rd_addr));
				h_add_spec_rs1_addr_matches_insn: assert(chk.spec_rs1_addr == rvfi_insn[19:15]);
				h_add_spec_rs2_addr_matches_insn: assert(chk.spec_rs2_addr == rvfi_insn[24:20]);
				h_add_spec_rd_addr_matches_insn: assert(chk.spec_rd_addr == rvfi_insn[11:7]);

				// Architectural x0 reads are always zero.
				h_add_x0_rs1_reads_zero: assert(chk.spec_rs1_addr != 0 ? 1'b1 : (rvfi_rs1_rdata == 32'd0));
				h_add_x0_rs2_reads_zero: assert(chk.spec_rs2_addr != 0 ? 1'b1 : (rvfi_rs2_rdata == 32'd0));

			end

			// Bridge the ISA-model's ADD decode to PicoRV32's internal decode flags.
			// RVFI signals lag the internal decode by (at least) one cycle; use prev_*.
			if (check && chk.spec_valid && !chk.spec_trap && !chk.mem_fault) begin
				h_spec_add_matches_core_decode: assert(prev_instr_add);
				h_spec_add_not_trap_decode: assert(!prev_instr_trap);
				h_spec_add_not_compressed: assert(!prev_latched_compr);
				h_spec_add_not_rvfi_trap: assert(!rvfi_trap[0]);
				// For ADD, both operands are always consumed.
				h_spec_add_rs1_captured: assert(prev_dbg_rs1val_valid);
				h_spec_add_rs2_captured: assert(prev_dbg_rs2val_valid);
			end

			// Strengthen the state space around the *exact* o_rd_wdata_match guard.
			// Use implication-style asserts so the constraints cannot be skipped due to X guards.
			h_spec_implies_rvfi_valid: assert(!do_spec_check || (rvfi_valid[0] === 1'b1));
			h_spec_implies_add: assert(!do_spec_rvfi_check || is_add);
			h_spec_rvfi_insn_known: assert(!do_spec_rvfi_check || no_x32(rvfi_insn));
			h_spec_rvfi_rs1_rdata_known: assert(!do_spec_rvfi_check || no_x32(rvfi_rs1_rdata));
			h_spec_rvfi_rs2_rdata_known: assert(!do_spec_rvfi_check || no_x32(rvfi_rs2_rdata));
