			// Track the (single) register-file writeback corresponding to the current ADD.
			// We intentionally do not assume a fixed latency between cpuregs_write and rvfi_valid.
			if (dbg_is_add && uut.cpuregs_write && uut.irq_state == 0) begin
				add_wb_pending <= 1;
				add_wb_rd <= uut.latched_rd;
				add_wb_data <= uut.cpuregs_wrdata;
				add_wb_rs1 <= uut.dbg_rs1val;
				add_wb_rs2 <= uut.dbg_rs2val;
				add_wb_rs_valid <= (uut.dbg_rs1val_valid && uut.dbg_rs2val_valid);
			end
			// Consume the tracked writeback when the checker is actually evaluating an ADD retirement.
			if (check && rvfi_valid[0] && chk.spec_valid && !chk.spec_trap && !chk.mem_fault && is_add && rvfi_rd_addr != 0) begin
				h_add_wb_pending: assert(add_wb_pending);
				h_add_wb_rd_matches: assert(add_wb_rd == rvfi_rd_addr);
				h_add_wb_operands_valid: assert(add_wb_rs_valid);
				h_add_rvfi_wdata_from_wb: assert(rvfi_rd_wdata == add_wb_data);
				add_wb_pending <= 0;
			end
		end

