			h_rvfi_insn_matches_q_insn_opcode: assert(!rvfi_valid[0] || rvfi_insn == uut.q_insn_opcode);
			h_rvfi_pc_wdata_matches_dbg_addr: assert(!rvfi_valid[0] || rvfi_pc_wdata == uut.dbg_insn_addr);

